R,C=19,22; seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  col=grid[r][c]
  if col==8 or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); cp=[]
  while q:
   x,y=q.pop(); cp.append((x,y))
   for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
    p=(x+dx,y+dy)
    if 0<=p[0]<R and 0<=p[1]<C and p not in seen and grid[p[0]][p[1]]==col:
     seen.add(p); q.append(p)
  comps.append((col,cp))
[(col,(min(x for x,y in cp),max(x for x,y in cp),min(y for x,y in cp),max(y for x,y in cp),len(cp))) for col,cp in comps]
